let state = { active: false, colorMode: 0 };
let lastTapTime = 0;

const getColorModeClass = (mode) => CONFIG.colorModes[mode].class;
const getColorModeName = (mode) => CONFIG.colorModes[mode].name;

const storage = {
  save() {
    try {
      localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
    } catch (e) {
      if (e.name === 'QuotaExceededError') {
        console.warn('localStorage quota exceeded');
      } else {
        console.warn('Failed to save state:', e);
      }
    }
  },
  load() {
    try {
      const saved = localStorage.getItem(CONFIG.storageKey);
      if (saved) {
        const parsed = JSON.parse(saved);
        if (parsed && typeof parsed === 'object') {
          state = { ...state, ...parsed };
        }
      }
    } catch (e) {
      console.warn('Failed to load state:', e);
    }
  }
};

const updateClasses = () => {
  const colorClasses = CONFIG.colorModes.map(m => m.class);
  el.circle.classList.remove('active', ...colorClasses);
  el.circle.setAttribute('aria-pressed', state.active);
  if (state.active) el.circle.classList.add('active');
  if (state.colorMode > 0) el.circle.classList.add(getColorModeClass(state.colorMode));
};

const updateUI = () => {
  const mainText = state.active ? 'Active!' : 'Click to activate';
  let hintParts = [mainText];

  if (CONFIG.isTouch) {
    hintParts.push(state.active ? 'Tap again to change color' : 'Tap twice to change color');
    hintParts.push('Use Reset to reset');
  } else {
    hintParts.push('Double-click or press C to change color');
    hintParts.push('Press R to reset');
  }

  el.hint.textContent = hintParts.join(' • ');

  const showMode = state.active && state.colorMode > 0;
  el.modeIndicator.classList.toggle('visible', showMode);
  if (showMode) el.modeIndicator.textContent = getColorModeName(state.colorMode);
};

const applyState = () => {
  updateClasses();
  updateUI();
};

const toggleActive = () => {
  state.active = !state.active;
  applyState();
  storage.save();
};

const cycleColor = () => {
  state.colorMode = (state.colorMode + 1) % CONFIG.colorModes.length;
  state.active = true;
  el.circle.classList.add('color-shifting');
  setTimeout(() => el.circle.classList.remove('color-shifting'), CONFIG.colorShiftDuration);
  applyState();
  storage.save();
};

const resetState = () => {
  state = { active: false, colorMode: 0 };
  applyState();
  storage.save();
};

const handleDblClick = (e) => {
  e.preventDefault();
  cycleColor();
};

const handleTouchEnd = (e) => {
  const now = Date.now();
  if (now - lastTapTime < CONFIG.tapDelay && lastTapTime > 0) {
    cycleColor();
    lastTapTime = 0;
  } else {
    lastTapTime = now;
  }
};

const handleKeyDown = (e) => {
  if (e.target !== el.circle) return;

  const key = e.key.toLowerCase();
  let handler;
  if (key === ' ' || key === 'enter') handler = toggleActive;
  else if (key === 'c') handler = cycleColor;
  else if (key === 'r') handler = resetState;

  if (handler) {
    e.preventDefault();
    handler();
  }
};

el.circle.addEventListener('click', toggleActive);
el.circle.addEventListener('dblclick', handleDblClick);
el.circle.addEventListener('touchend', handleTouchEnd);
el.circle.addEventListener('blur', () => { lastTapTime = 0; });

